code_sketch:
# frozen_string_literal: true

class Money
  attr_reader :cents, :currency

  def initialize(cents, currency)
    @cents = cents
    @currency = currency
    freeze
  end

  def plus(other)
    Money.new(@cents + other.cents, @currency)
  end
end

